use std::collections::HashMap;
use std::io::{self, BufRead, Write};

// Each open transaction keeps an undo log of (key, previous value) pairs,
// recorded before the first write of every change. Rolling back replays the
// log in reverse; committing discards all open logs, keeping the changes.
struct Store {
    data: HashMap<String, i64>,
    undo: Vec<Vec<(String, Option<i64>)>>,
}

impl Store {
    fn new() -> Self {
        Store {
            data: HashMap::new(),
            undo: Vec::new(),
        }
    }

    fn record(&mut self, key: &str) {
        let old = self.data.get(key).copied();
        if let Some(log) = self.undo.last_mut() {
            log.push((key.to_string(), old));
        }
    }

    fn set(&mut self, key: &str, value: i64) {
        self.record(key);
        self.data.insert(key.to_string(), value);
    }

    fn delete(&mut self, key: &str) {
        self.record(key);
        self.data.remove(key);
    }

    fn begin(&mut self) {
        self.undo.push(Vec::new());
    }

    fn rollback(&mut self) -> bool {
        match self.undo.pop() {
            None => false,
            Some(log) => {
                for (key, old) in log.into_iter().rev() {
                    match old {
                        Some(v) => {
                            self.data.insert(key, v);
                        }
                        None => {
                            self.data.remove(&key);
                        }
                    }
                }
                true
            }
        }
    }

    fn commit(&mut self) -> bool {
        if self.undo.is_empty() {
            false
        } else {
            self.undo.clear();
            true
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut store = Store::new();

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        match parts[0] {
            "set" if parts.len() >= 3 => {
                if let Ok(v) = parts[2].parse::<i64>() {
                    store.set(parts[1], v);
                }
            }
            "get" if parts.len() >= 2 => match store.data.get(parts[1]) {
                Some(v) => writeln!(out, "{}", v).unwrap(),
                None => writeln!(out, "NULL").unwrap(),
            },
            "delete" if parts.len() >= 2 => store.delete(parts[1]),
            "count" if parts.len() >= 2 => {
                if let Ok(v) = parts[1].parse::<i64>() {
                    let n = store.data.values().filter(|&&x| x == v).count();
                    writeln!(out, "{}", n).unwrap();
                }
            }
            "begin" => store.begin(),
            "rollback" => {
                if !store.rollback() {
                    writeln!(out, "NO TRANSACTION").unwrap();
                }
            }
            "commit" => {
                if !store.commit() {
                    writeln!(out, "NO TRANSACTION").unwrap();
                }
            }
            _ => {}
        }
    }
}
